#if UNITY_EDITOR
using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine; using UnityEngine.AI; using UnityEngine.UI; using NightGrove; using System.IO;
public static class NightGroveSceneBuilder {
 [MenuItem("Night Grove/Create Demo Scene")]
 public static void Create(){ Directory.CreateDirectory("Assets/Scenes"); var scene=EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single); var gm=new GameObject("GameManager"); gm.AddComponent<GameManager>(); var player=GameObject.CreatePrimitive(PrimitiveType.Capsule); player.name="PlayerRig_ReplaceWithXROrigin"; player.transform.position=new Vector3(0,1,0); player.AddComponent<CharacterController>(); player.AddComponent<ArmSwingLocomotion>(); player.AddComponent<PlayerVitals>(); var cam=new GameObject("Head"); cam.transform.SetParent(player.transform); cam.transform.localPosition=new Vector3(0,0.7f,0); var camera=cam.AddComponent<Camera>(); camera.tag="MainCamera"; var left=new GameObject("LeftHand"); left.transform.SetParent(player.transform); left.transform.localPosition=new Vector3(-.3f,.5f,.3f); var right=new GameObject("RightHand"); right.transform.SetParent(player.transform); right.transform.localPosition=new Vector3(.3f,.5f,.3f); var locomotion=player.GetComponent<ArmSwingLocomotion>(); locomotion.head=cam.transform; locomotion.leftHand=left.transform; locomotion.rightHand=right.transform; for(int i=0;i<3;i++){var r=GameObject.CreatePrimitive(PrimitiveType.Sphere); r.name="Relic_"+i; r.transform.position=new Vector3(i*5-5,1,5); r.transform.localScale=Vector3.one*.45f; r.AddComponent<SphereCollider>().isTrigger=true; r.AddComponent<RelicPickup>();} var gate=GameObject.CreatePrimitive(PrimitiveType.Cube); gate.name="ExtractionGate"; gate.transform.position=new Vector3(0,1,14); gate.transform.localScale=new Vector3(4,2,.3f); gate.AddComponent<BoxCollider>().isTrigger=true; gate.AddComponent<ExtractionGate>(); var stalker=GameObject.CreatePrimitive(PrimitiveType.Capsule); stalker.name="Stalker"; stalker.transform.position=new Vector3(0,1,8); var nav=stalker.AddComponent<NavMeshAgent>(); stalker.AddComponent<StalkerAI>(); RenderSettings.ambientLight=new Color(.02f,.02f,.04f); EditorSceneManager.SaveScene(scene,"Assets/Scenes/NightGroveDemo.unity"); Selection.activeGameObject=player; EditorUtility.DisplayDialog("Night Grove","Demo scene created. Replace PlayerRig with an XR Origin and bake a NavMesh before testing the stalker.","OK"); }
}
#endif
